    wait(lambda: all('cluster_known_nodes:6' in cmd(i,'cluster','info') for i in range(6)))
    ranges = [(0,5460),(5461,10922),(10923,16383)]
    for i, slots in enumerate(ranges): cmd(i,'cluster','addslotsrange',*slots)
    ids = [cmd(i,'cluster','myid') for i in range(6)]
    for i in range(3): cmd(i+3,'cluster','replicate',ids[i])
    wait(lambda: all('cluster_state:ok' in cmd(i,'cluster','info') for i in range(6)))
    wait(lambda: all('master_link_status:up' in cmd(i,'info','replication') for i in range(3,6)))
    print('Before failure:', json.dumps(cmd(0,'cluster','shards')), flush=True)
    paused = procs[1].pid; os.kill(paused,signal.SIGSTOP)
    wait(lambda: cmd(4,'role')[0]=='master')
    wait(lambda: any('fail' in n.split()[2] and n.split()[0]==ids[1] for n in cmd(0,'cluster','nodes').splitlines()))
