    print('REPRO_STATE='+str(pathlib.Path(root)/'state.json'),flush=True)
finally:
    for i,p in enumerate(procs):
        if p.pid==paused: continue
        try: cmd(i,'shutdown','nosave')
        except (RuntimeError,json.JSONDecodeError): pass
        p.wait(timeout=5)
    if paused:
        os.kill(paused,signal.SIGCONT)
        try: cmd(1,'shutdown','nosave')
