start_cluster 3 3 {tags {external:skip cluster}} {
    set primary_id [R 1 cluster myid]
    set replica_id [R 4 cluster myid]
    set expected_slots {5462 10922}

    test "CLUSTER SHARDS reports slot ranges from primaries and replicas" {
        for {set j 0} {$j < 6} {incr j} {
            set shards [R $j cluster shards]
            assert_equal 3 [llength $shards]
            set shard [cluster_shards_find_by_node $shards $primary_id]
            assert_equal $expected_slots [dict get $shard slots]
            assert_equal 2 [llength [dict get $shard nodes]]
        }
    }

    test "CLUSTER SHARDS reports discontinuous slot ranges" {
        R 1 cluster delslots 8000
        set shard [cluster_shards_find_by_node [R 1 cluster shards] $primary_id]
        assert_equal {5462 7999 8001 10922} [dict get $shard slots]
        R 1 cluster addslots 8000
        wait_for_cluster_propagation
    }

    set paused_pid [srv -1 pid]
    test "CLUSTER SHARDS retains slot ranges after primary failure and failover" {
        wait_for_condition 1000 50 {
            [s -4 master_link_status] eq "up"
        } else {
            fail "Replica did not sync with its primary"
        }
        pause_process $paused_pid
        wait_for_condition 1000 50 {
            [s -4 role] eq "master"
        } else {
            fail "Replica did not fail over"
        }

        foreach j {0 2 3 4 5} {
            wait_for_condition 1000 50 {
                [cluster_has_flag [cluster_get_node_by_id $j $primary_id] fail] &&
                [lindex [lindex [R $j cluster slots] 1] 2 2] eq $replica_id
            } else {
                fail "Node $j did not learn about the failover"
            }
            set shard [cluster_shards_find_by_node [R $j cluster shards] $primary_id]
            assert_equal 2 [llength [dict get $shard nodes]]
            foreach node [dict get $shard nodes] {
                assert_equal master [dict get $node role]
            }
            assert_equal $expected_slots [dict get $shard slots]
            assert_equal $expected_slots [dict get [cluster_shards_find_by_node [R $j cluster shards] $replica_id] slots]
        }
    }
    resume_process $paused_pid

    test "CLUSTER SHARDS retains slot ranges after the old primary rejoins" {
        wait_for_condition 1000 50 {
            [s -1 role] eq "slave"
        } else {
            fail "Old primary did not become a replica"
        }
        wait_for_cluster_propagation
        for {set j 0} {$j < 6} {incr j} {
            set shard [cluster_shards_find_by_node [R $j cluster shards] $primary_id]
            assert_equal $expected_slots [dict get $shard slots]
        }
    }

    test "CLUSTER SHARDS reports empty slots for a shard without slot ownership" {
        R 4 cluster flushslots
        set shards [R 4 cluster shards]
        assert_equal 3 [llength $shards]
        set shard [cluster_shards_find_by_node $shards $replica_id]
        assert_equal {} [dict get $shard slots]
        assert_equal 2 [llength [dict get $shard nodes]]
    }
}
'''
